CustomField.formula:
IF(A_os_Laborados__c = 1, 12,
    IF(A_os_Laborados__c = 2, 14,
        IF(A_os_Laborados__c = 3, 16,
            IF(A_os_Laborados__c = 4, 18,
                IF(A_os_Laborados__c = 5, 20,
                    IF(AND(A_os_Laborados__c >= 6, A_os_Laborados__c <= 10), 22,
                        IF(AND(A_os_Laborados__c >= 11, A_os_Laborados__c <= 15), 24,
                            IF(AND(A_os_Laborados__c >= 16, A_os_Laborados__c <= 20), 26,
                                IF(AND(A_os_Laborados__c >= 21, A_os_Laborados__c <= 25), 28,
                                    IF(AND(A_os_Laborados__c >= 26, A_os_Laborados__c <= 30), 30,
                                        IF(AND(A_os_Laborados__c >= 31, A_os_Laborados__c <= 36), 32, 0)
                                    )
                                )
                            )
                        )
                    )
                )
            )
        )
    )
)
